class Solution {
    public long[] productOfOthers(int[] nums) {
        int n = nums.length;
        long[] prefix = new long[n], suffix = new long[n], out = new long[n];
        prefix[0] = 1;
        for (int i = 1; i < n; i++) prefix[i] = prefix[i - 1] * nums[i - 1];
        suffix[n - 1] = 1;
        for (int i = n - 2; i >= 0; i--) suffix[i] = suffix[i + 1] * nums[i + 1];
        for (int i = 0; i < n; i++) out[i] = prefix[i] * suffix[i];
        return out;
    }
}

